import json, sqlite3, os, re
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, unquote
import markdown, bleach
os.makedirs('/data',exist_ok=True)
def db():
 c=sqlite3.connect('/data/wiki.db'); c.row_factory=sqlite3.Row; return c
with db() as c:
 c.executescript('CREATE TABLE IF NOT EXISTS pages(slug TEXT PRIMARY KEY,title TEXT,body TEXT,author TEXT,version INTEGER,updated TEXT); CREATE TABLE IF NOT EXISTS revisions(slug TEXT,title TEXT,body TEXT,author TEXT,version INTEGER,updated TEXT);')
 if not c.execute('SELECT 1 FROM pages').fetchone():
  c.execute("INSERT INTO pages VALUES(?,?,?,?,1,datetime('now'))",('home','Study group wiki','# Welcome to our study wiki\n\nWrite what you learn and explore each other’s notes.\n\n## Getting started\n\n- Select **New page** to add notes.\n- Add your name so others know who contributed.\n- Use headings, lists, links, tables, and fenced code blocks.\n- Link pages with \u0060[Topic](/#topic-slug)\u0060.\n- Save before switching pages.\n\nAnyone with this link can read and edit. Keep private information elsewhere.','Study group'))
  c.execute('INSERT INTO revisions SELECT * FROM pages')
def render(body):
 return bleach.clean(markdown.markdown(body,extensions=['fenced_code','tables']),tags=set(bleach.sanitizer.ALLOWED_TAGS)|{'p','h1','h2','h3','h4','h5','h6','pre','code','hr','br','table','thead','tbody','tr','th','td'},attributes={'a':['href','title'],'code':['class']},strip=True)
class Handler(BaseHTTPRequestHandler):
 def respond(self,obj,status=200):
  data=json.dumps(obj).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(data))); self.send_header('Cache-Control','no-store'); self.end_headers(); self.wfile.write(data)
 def do_GET(self):
  path=unquote(urlparse(self.path).path)
  if path=='/':
   data=open('/app/index.html','rb').read(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.end_headers(); self.wfile.write(data); return
  with db() as c:
   if path=='/api/pages':
    return self.respond([dict(r) for r in c.execute('SELECT slug,title,author,version,updated FROM pages ORDER BY updated DESC')])
   m=re.fullmatch(r'/api/pages/([a-z0-9-]+)(/history)?',path)
   if m:
    if m[2]: return self.respond([dict(r) for r in c.execute('SELECT * FROM revisions WHERE slug=? ORDER BY version DESC',(m[1],))])
    row=c.execute('SELECT * FROM pages WHERE slug=?',(m[1],)).fetchone()
    if row:
     obj=dict(row); obj['html']=render(obj['body']); return self.respond(obj)
  self.respond({'error':'Page not found'},404)
 def do_POST(self):
  try:
   length=int(self.headers.get('Content-Length',0))
   if length>262144: return self.respond({'error':'Page is too large (maximum 256 KB)'},413)
   origin=self.headers.get('Origin')
   if origin and urlparse(origin).netloc!=self.headers.get('Host'): return self.respond({'error':'Cross-origin write refused'},403)
   obj=json.loads(self.rfile.read(length))
   if self.path=='/api/preview': return self.respond({'html':render(str(obj.get('body','')))})
   if self.path!='/api/pages': return self.respond({'error':'Not found'},404)
   slug=obj.get('slug',''); title=obj.get('title','').strip(); body=obj.get('body',''); author=obj.get('author','').strip() or 'Anonymous'
   if not re.fullmatch('[a-z0-9-]{1,80}',slug) or not title or len(title)>160 or not isinstance(body,str): return self.respond({'error':'Use a title (up to 160 characters) and a valid page slug.'},400)
   with db() as c:
    c.execute('BEGIN IMMEDIATE')
    old=c.execute('SELECT version FROM pages WHERE slug=?',(slug,)).fetchone()
    version=old['version'] if old else 0
    if obj.get('version',0)!=version: return self.respond({'error':'Someone saved this page first, or this slug already exists. Copy your changes, then reopen the page to merge them.'},409)
    c.execute("INSERT OR REPLACE INTO pages VALUES(?,?,?,?,?,datetime('now'))",(slug,title,body,author[:100],version+1))
    c.execute('INSERT INTO revisions SELECT * FROM pages WHERE slug=?',(slug,))
   self.respond({'slug':slug,'version':version+1})
  except (ValueError,TypeError,AttributeError): self.respond({'error':'Invalid request'},400)
print('Study wiki listening on port 3000; persistent database /data/wiki.db',flush=True)
ThreadingHTTPServer(('0.0.0.0',3000),Handler).serve_forever()

