import os, sqlite3, re
from flask import Flask, request, redirect, render_template_string, abort
import markdown, bleach
app=Flask(__name__)
app.config['MAX_CONTENT_LENGTH']=262144
os.makedirs('/data',exist_ok=True)
def db():
 c=sqlite3.connect('/data/wiki.db',timeout=20); c.row_factory=sqlite3.Row; return c
with db() as c:
 c.executescript('CREATE TABLE IF NOT EXISTS pages(slug TEXT PRIMARY KEY,title TEXT,body TEXT,author TEXT,version INTEGER,updated TEXT); CREATE TABLE IF NOT EXISTS revisions(slug TEXT,title TEXT,body TEXT,author TEXT,version INTEGER,updated TEXT);')
 c.execute("INSERT OR IGNORE INTO pages VALUES('home','Welcome',?,'Study group',1,datetime('now'))",('# Study group wiki\n\nA shared place for what we learn.\n\n## Start here\n\n- Click **New page** to write Markdown notes.\n- Add your name and save your page.\n- Browse the sidebar to read everyone’s pages.\n- Link notes using [Welcome](/page/home).\n- Use **History** to read and copy earlier versions.\n\nAnyone with this link can read and edit.\n',))
 c.execute("INSERT INTO revisions SELECT * FROM pages WHERE slug='home' AND NOT EXISTS(SELECT 1 FROM revisions WHERE slug='home')")
def rendered(body):
 return bleach.clean(markdown.markdown(body,extensions=['tables','fenced_code']),tags=set(bleach.sanitizer.ALLOWED_TAGS)|{'p','h1','h2','h3','h4','h5','h6','pre','code','hr','br','table','thead','tbody','tr','th','td'},attributes={'a':['href','title']},strip=True)
