</style><header><div><strong>Study group wiki</strong><br><small>A shared place for what we learn.</small></div><a class="button" href="/new">+ New page</a></header><main><aside><form action="/"><label>Find a page<input name="q" value="{{q}}" placeholder="Search notes…"></label><button>Search</button></form><nav>{% for p in pages %}<a href="/page/{{p.slug}}">{{p.title}}</a>{% else %}<p>No matching pages.</p>{% endfor %}</nav><p><small>Anyone with the link can read and edit. Revisions are saved.</small></p></aside><article>{% if error %}<p class="error" role="alert">{{error}}</p>{% endif %}
{% if edit %}<h1>{{title}}</h1><form method="post" action="/save" id="editor"><input type="hidden" name="version" value="{{page.version}}"><label>Title<input required name="title" value="{{page.title}}" maxlength="160"></label><label>Page address (lowercase letters, numbers, hyphens)<input required name="slug" value="{{page.slug}}" pattern="[a-z0-9-]{1,80}" maxlength="80" {% if page.version|int > 0 %}readonly{% endif %}></label><label>Your name<input name="author" value="{{page.author}}" maxlength="100"></label><label>Markdown<textarea name="body">{{page.body}}</textarea></label><button>Save page</button> <button formaction="/preview">Preview</button> <a href="/page/{{page.slug or 'home'}}">Cancel</a></form>{% if preview %}<h2>Preview</h2>{{preview|safe}}{% endif %}
