def edit(slug): return view(title='Edit page',edit=True,page=get(slug))
@app.get('/history/<slug>')
def history(slug):
 p=get(slug)
 with db() as c: rows=c.execute('SELECT * FROM revisions WHERE slug=? ORDER BY version DESC',(slug,)).fetchall()
 return view(title='History',page=p,history=rows)
@app.before_request
def origin_check():
 if request.method=='POST':
  from urllib.parse import urlparse
  origin=request.headers.get('Origin')
  if origin and urlparse(origin).netloc!=request.host: abort(403)
@app.post('/preview')
def preview(): return view(title='Preview page',edit=True,page=request.form,preview=rendered(request.form.get('body','')))
@app.post('/save')
def save():
 p=request.form.to_dict()
 def error(message,status): return view(title='Edit page',edit=True,page=p,error=message),status
 if not re.fullmatch('[a-z0-9-]{1,80}',p.get('slug','')) or not p.get('title','').strip() or len(p['title'])>160: return error('Enter a title and a valid page address.',400)
 try: version=int(p.get('version',0))
 except ValueError: return error('Invalid revision.',400)
 with db() as c:
  c.execute('BEGIN IMMEDIATE')
  old=c.execute('SELECT version FROM pages WHERE slug=?',(p['slug'],)).fetchone()
  if (old['version'] if old else 0)!=version: return error('This page was saved by someone else or the address already exists. Your draft is preserved below. Copy it, reopen the current page, and merge your changes.',409)
  c.execute("INSERT OR REPLACE INTO pages VALUES(?,?,?,?,?,datetime('now'))",(p['slug'],p['title'].strip(),p.get('body',''),p.get('author','').strip()[:100] or 'Anonymous',version+1))
  c.execute('INSERT INTO revisions SELECT * FROM pages WHERE slug=?',(p['slug'],))
 return redirect('/page/'+p['slug'])

